const d=window.PORTFOLIO;const site=window.SITE||{base:'',url:x=>x,html:x=>x};const mainEl=document.querySelector('main');const main={get innerHTML(){return mainEl.innerHTML},set innerHTML(h){mainEl.innerHTML=site.html(h)}};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=u=>{try{const x=new URL(u,location.origin);return ['http:','https:'].includes(x.protocol)?x.href:''}catch{return ''}};const projects=d.projects;const name=d.name||'Your name';const btn=(href,label,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="${esc(href)}">${label} <span aria-hidden="true"></span></a>`;const heading=(label,title,desc='')=>`<div class="page-title"><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lead">${desc}</p></div>`;const empty=t=>`<div class="empty">${t}</div>`;
const cards=window.CEEL.cards;
function cv(){return d.cv&&safe(d.cv)?`<div class="actions"><a class="button" href="${esc(safe(d.cv))}" download="annonuevo_resume.pdf">Download R\u00e9sum\u00e9</a><a class="button secondary" href="${esc(safe(d.cv))}" target="_blank" rel="noopener">View R\u00e9sum\u00e9 Online</a></div>`:empty('The latest CV PDF has not been provided yet. Download and online viewing will be available once it is added.');}
function skills(){return d.skills.length?`<div class="grid">${d.skills.map(s=>`<article class="skill-box"><span class="tool-mark" aria-hidden="true">${esc(s.monogram||s.category.charAt(0))}</span><h3>${esc(s.category)}</h3><div class="tags">${s.items.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></article>`).join('')}</div>`:empty('Verified skills are awaiting the creator\u0027s details. Skills will be grouped by discipline without invented proficiency percentages.');}
function about(){return `<div class="two"><div><span class="eyebrow">A LITTLE ABOUT ME</span><h2>Curiosity meets<br>purposeful creation.</h2><p>${esc(d.bio||'This space will introduce the creator\u0027s background, approach, areas of expertise and professional goals.')}</p>${btn('/about','More about me',true)}</div><dl class="facts">${[['Full name',d.name],['Focus',d.focus],['Location',d.location],['Email',d.email],['Phone',d.phone],['Specialization',d.specialization],['Experience',d.experienceSummary],['Education',d.occupation]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'To be provided')}</dd></div>`).join('')}</dl></div>`}
function aboutPage(){
 const biography=[
 "I'm Diane M. Annonuevo, a third-year Bachelor of Science in Information Technology student at City College of Calamba with a growing interest in web design, graphic design, and technology.",
 "Since 2022, I've been accepting freelance commissions involving work immersion portfolios, web design projects, and various basic editing tasks. These experiences have given me opportunities to explore different creative projects, work with client requirements, and gradually develop my design skills.",
 "I'm also exploring graphic design and continuously learning how to improve my creativity and visual communication. On the technical side, I have foundational knowledge of coding and hands-on experience in assembling and disassembling computers, setting up printers, working with network cables, and performing basic networking tasks.",
 "While I'm still developing my skills, I enjoy learning through practical experience and exploring how design and technology can work together to create useful and meaningful digital solutions."
 ];
 const facts=[['Full Name',d.name],['Location',d.location],['Education','BS Information Technology'],['School','City College of Calamba'],['Creative Focus','Web & Graphic Design'],['Freelance Commissions','Since 2022'],['Technical Interests','Computer Hardware, IT Support, Basic Networking'],['Current Status','Student & Aspiring Designer']];
 const offerings=[
 {title:'Creative Commissions',icon:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>',description:"Since 2022, I've worked on commissioned projects such as work immersion portfolios, basic editing tasks, and web design projects. These experiences have helped me strengthen my creativity, attention to detail, and ability to work with different client requirements."},
 {title:'Web & Graphic Design',icon:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 9v11M6 6.5h.01M9 6.5h.01"/>',description:"I'm continuously exploring web and graphic design, from creating layouts and editing visual materials to learning how to build functional and visually engaging web interfaces."},
 {title:'Technical & IT Skills',icon:'<rect x="5" y="5" width="14" height="14" rx="2"/><path d="M9 9h6v6H9zM9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M2 15h3M19 9h3M19 15h3"/>',description:'I have foundational experience in computer assembly and disassembly, printer setup, network cabling, basic networking, and coding. I continue to develop these skills through academic activities and hands-on practice.'}
 ];
 return `<div class="about-page">${heading('THE PERSON BEHIND THE WORK','A little about me.','Get to know my background, creative journey, and growing interest in design and technology.')}<section class="section about-intro" aria-labelledby="journey-title"><div class="about-biography"><span class="eyebrow">MY CREATIVE JOURNEY</span><h2 id="journey-title">Where creativity meets technology.</h2>${biography.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="actions">${btn('/projects','Explore My Projects')}</div></div><aside class="about-information" aria-labelledby="information-title"><span class="eyebrow">AT A GLANCE</span><h2 id="information-title">A few things about me.</h2><dl class="facts">${facts.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></aside></section><section class="section about-offerings" aria-labelledby="what-i-do"><div class="section-head"><div><span class="eyebrow">DESIGN &amp; TECHNOLOGY</span><h2 id="what-i-do">What I Do</h2></div></div><div class="grid">${offerings.map(o=>`<article class="card"><div class="card-body"><span class="about-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${o.icon}</svg></span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p></div></article>`).join('')}</div></section><section class="about-philosophy" aria-labelledby="philosophy-title"><span class="eyebrow">MY APPROACH</span><h2 id="philosophy-title">Learning, creating, and improving.</h2><p>${esc("I believe that creativity and technical knowledge can complement each other. Whether I'm designing a layout, working on a commission, or learning something technical, I approach each task as an opportunity to improve my skills and gain experience.")}</p><p>${esc("I'm still exploring different areas of IT and design, but I'm motivated to keep learning, experimenting, and creating work that I can be proud of.")}</p></section></div>`;
}

function timeline(items,type){return items.length?`<div class="timeline">${items.map(x=>`<article><span class="eyebrow">${esc(x.dates||x.year)}</span><h3>${esc(x.position||x.degree||x.name)}</h3><p>${esc(x.organization||x.institution)}${x.location?'  |  '+esc(x.location):''}</p><p>${esc(x.description||'')}</p>${x.responsibilities?`<ul>${x.responsibilities.map(y=>`<li>${esc(y)}</li>`).join('')}</ul>`:''}${x.credentialId?`<p>Credential ID: ${esc(x.credentialId)}</p>`:''}</article>`).join('')}</div>`:empty(`${type} will appear here once the creator supplies verified details.`);}
function contact(){return window.CONTACT.render();}

function capabilityIcon(kind){const paths={creative:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 9v11"/>',technical:'<rect x="5" y="5" width="14" height="14" rx="2"/><path d="M9 9h6v6H9zM9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M19 9h3M2 15h3M19 15h3"/>',admin:'<path d="M7 3h7l4 4v14H7zM14 3v5h4M10 12h5M10 16h5"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>'};return '<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+paths[kind]+'</svg>';}
function skillsPage(){const creative=d.skillGroups[0];return '<div class="profile-page skills-page">'+heading('TOOLS & CAPABILITIES','The skills behind the work.','A combination of creative skills, technical knowledge, and practical experience.')+
'<section class="section creative-section" aria-labelledby="creative-title"><div class="section-head"><div><span class="eyebrow">CREATIVE PRACTICE</span><h2 id="creative-title">'+esc(creative.name)+'</h2></div></div><div class="grid software-grid">'+creative.tools.map(t=>'<article class="skill-box"><span class="tool-mark" aria-hidden="true">'+esc(t.mark)+'</span><h3>'+esc(t.name)+'</h3><p>'+esc(t.description)+'</p></article>').join('')+'</div><div class="creative-extras">'+creative.additional.map(t=>'<div><h3>'+esc(t.name)+'</h3><p>'+esc(t.description)+'</p></div>').join('')+'</div></section><section class="section capability-section" aria-label="Technical, administrative and professional capabilities"><div class="capability-grid">'+d.skillGroups.slice(1).map((g,i)=>'<article class="skill-box"><span class="about-icon">'+capabilityIcon(['technical','admin','people'][i])+'</span><h2>'+esc(g.name)+'</h2><p>'+esc(g.intro)+'</p><ul class="capability-items">'+g.items.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul></article>').join('')+'</div></section></div>';}
function experiencePage(){return '<div class="profile-page experience-page">'+heading('THE JOURNEY','Experience that shapes the work.','Creative commissions, customer-facing work, and seasonal public-service experience.')+'<section class="section" aria-labelledby="experience-title"><h2 id="experience-title" class="visually-hidden">Work experience</h2><div class="timeline career-timeline">'+d.experience.map(x=>'<article><div class="timeline-date">'+esc(x.dates)+'</div><div class="timeline-content"><span class="entry-kind">'+esc(x.type)+'</span><h3>'+esc(x.position)+'</h3><p class="entry-organization">'+esc(x.organization)+'</p><p>'+esc(x.description)+'</p><h4>Responsibilities</h4><ul>'+x.responsibilities.map(y=>'<li>'+esc(y)+'</li>').join('')+'</ul></div></article>').join('')+'</div></section></div>';}
function educationPage(){return '<div class="profile-page education-page">'+heading('LEARNING & GROWTH','Education & r\u00e9sum\u00e9.','My academic background, technical foundation, and professional experience in one place.')+'<section class="section" aria-labelledby="academic-title"><div class="section-head"><div><span class="eyebrow">ACADEMIC BACKGROUND</span><h2 id="academic-title">My education</h2></div></div><div class="timeline academic-timeline">'+d.education.map((x,i)=>'<article class="'+(i<2?'academic-featured':'academic-compact')+'"><span class="timeline-date">'+esc(x.dates)+'</span><div class="timeline-content"><h3>'+esc(x.degree)+'</h3><p class="entry-organization">'+esc(x.institution)+'</p>'+(x.status?'<span class="study-status">'+esc(x.status)+'</span>':'')+'</div></article>').join('')+'</div></section><section class="resume-card" id="resume" aria-labelledby="resume-title"><div><span class="eyebrow">THE FULL PICTURE</span><h2 id="resume-title">My R\u00e9sum\u00e9</h2><p>Learn more about my educational background, work experience, and professional skills through my r\u00e9sum\u00e9.</p><span class="small-note">PDF document</span></div><div>'+cv()+'</div></section></div>';}

function render(){let path=decodeURI(location.pathname);if(site.base&&(path===site.base||path.startsWith(site.base+'/')))path=path.slice(site.base.length);path=path.replace(/\/$/,'')||'/';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===path||(a.getAttribute('href')==='/projects'&&path.startsWith('/projects/'))));let title='Home';if(path==='/'){main.innerHTML=`<section class="hero"><div><div class="pill"><span class="dot"></span> THE INTERSECTION OF DESIGN & TECHNOLOGY</div><h1>Hi, I\u0027m Diane.<br>I create with<br><em>purpose</em></h1><p class="lead">${esc(d.bio||'A space for thoughtful ideas, useful digital experiences, and the work that brings them to life.')}</p><div class="actions">${btn('/projects','Explore my work')}${btn('/contact','Let\u0027s talk',true)}</div><a class="text-link" href="/education#resume">View resume & credentials </a></div><div class="hero-art">${d.photo&&safe(d.photo)?`<img src="${esc(d.photo.startsWith('/')?d.photo:safe(d.photo))}" alt="Portrait of ${esc(name)}">`:'<div class="portrait-placeholder"><strong>d.</strong><small>YOUR PORTRAIT HERE</small></div>'}<div class="floating top">Design &amp; development</div><div class="floating"><b>Ideas into experiences.</b>One thoughtful detail at a time.</div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE PORTFOLIO</span><h2>Selected work<span style="color:var(--accent)">.</span></h2><p>Creative outputs from my CEEL 301 Graphic Design coursework.</p></div><a class="text-link" href="/projects">All projects </a></div><div class="grid">${cards(projects.slice(0,3))}</div></section><section class="section">${about()}</section><section class="section"><div class="section-head"><div><span class="eyebrow">MY TOOLKIT</span><h2>Skills with intention.</h2></div><a class="text-link" href="/skills">Explore skills </a></div>${skills()}</section><div class="callout"><div><span class="eyebrow">HAVE SOMETHING IN MIND?</span><h2>Let\u0027s turn your next idea<br>into something real.</h2></div>${btn('/contact','Start a conversation')}</div>`;}else if(path==='/about'){title='About';main.innerHTML=aboutPage();}else if(path==='/skills'){title='Skills';main.innerHTML=skillsPage();}else if(path==='/experience'){title='Experience';main.innerHTML=experiencePage();}else if(path==='/education'){title='Education';main.innerHTML=educationPage();}else if(path==='/cv'){location.replace(site.url('/education#resume'));return;}else if(path==='/contact'){title='Contact';main.innerHTML=contact();window.CONTACT.bind();}else if(path==='/projects'){title='Projects';main.innerHTML=window.CEEL.listing();window.CEEL.bindListing();}else if(path.startsWith('/projects/')){const p=projects.find(x=>x.slug===path.split('/')[2]&&path.split('/').length===3);if(p){title=p.title;main.innerHTML=window.CEEL.detail(p);window.CEEL.bindLightbox(p);}else{title='Project not found';main.innerHTML=heading('404','Project not found.','This project does not exist.')+btn('/projects','Browse projects');}}else{title='Page not found';main.innerHTML=heading('404','Page not found.','The page you are looking for does not exist.')+btn('/','Return home');}document.title=`${title} | ${d.siteName||'Portfolio'}`;}
let theme;try{theme=localStorage.getItem('portfolio-theme')}catch{}document.documentElement.dataset.theme=theme||'light';document.querySelector('.theme').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('portfolio-theme',next)}catch{}});document.querySelector('.menu').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.querySelector('#footer-name').textContent=(d.name?d.name+'  |  ':'')+'IT Student';const socials=[['linkedin','LinkedIn'],['github','GitHub']].filter(([k])=>d[k]&&safe(d[k]));if(socials.length)document.querySelector('#socials').innerHTML=socials.map(([k,l])=>`<a href="${esc(safe(d[k]))}" target="_blank" rel="noopener">${l} </a>`).join('');render();
// Header and footer links are written from the site root; point them into the base folder.
if(site.base)document.querySelectorAll('header a[href^="/"],footer a[href^="/"]').forEach(a=>a.setAttribute('href',site.url(a.getAttribute('href'))));
